```python
# ==================== SR TOOLS ENDPOINTS (RM-003) ====================

@app.get("/list_files")
async def list_files():
    """Список ключевых файлов из core_map (быстрее /api/tree)"""
    try:
        core_map = kernel.get_module("simbiosis/core_map")
        files = []
        # Из ядра
        km = core_map.get("kernel_modules", {}).get("modules", {})
        for mod in km.values():
            files.append(mod.get("file", ""))
        # Репо ключевые
        repo = core_map.get("repository", {}).get("files", {})
        files.extend(list(repo.keys()))
        return {"files": list(set(files)), "count": len(files)}
    except Exception as e:
        return {"error": str(e)}

@app.get("/read_file/{path:path}")
async def read_file_endpoint(path: str):
    """Raw файл из репо (для фронта/бота)"""
    content = await file_reader.read(path)
    if content is None:
        raise HTTPException(404, f"Файл {path} не найден")
    return {"path": path, "content": content}

@app.post("/validate_patch")
async def validate_patch(patch: dict):
    """Dry-run патча (без GitHub)"""
    is_valid, msg = validate_patch_structure(patch)
    if not is_valid:
        return {"valid": False, "error": msg}

    # Если мульти — валидим первый (упрощённо)
    if "patches" in patch:
        subpatch = patch["patches"][0]
    else:
        subpatch = patch

    file_path = subpatch.get("file_path") or subpatch.get("target_module") + ".json"
    content = await file_reader.read(file_path)
    if not content:
        return {"valid": False, "error": f"Файл {file_path} не найден"}

    try:
        current_json = json.loads(content)
        if "changes" in subpatch:
            result = await apply_batch_patch_dry_run(current_json, subpatch["changes"])
            return {
                "valid": result["success"],
                "applied": len(result["applied"]),
                "failed": result["failed"],
                "diff": result["diff"][:10],
                "preview": json.dumps(result["result_content"], indent=2)[:1000] + "..."
            }
        else:
            return {"valid": True, "message": "Full content OK"}
    except json.JSONDecodeError:
        return {"valid": True if "content" in subpatch else False, "message": "Non-JSON файл (Python OK с content)"}
```

